/bin/bash -lc "python - <<'PY'
from openpyxl import load_workbook
wb=load_workbook('inputs/data.xlsx',read_only=True,data_only=True)
ws=wb.active
headers=[c.value for c in next(ws.iter_rows())]
idx={h:i for i,h in enumerate(headers) if h is not None}
for col in ['Efficacy','BMI','Groups']:
 vals=[r[idx[col]] for r in ws.iter_rows(min_row=2,values_only=True)]
 uniq=[]
 for v in vals:
  if v not in uniq: uniq.append(v)
 print(col,'nonmissing',sum(v is not None for v in vals),'missing',sum(v is None for v in vals),'unique',uniq)
PY"
